<?php
require_once __DIR__ . '/_bootstrap.php';customerPostCsrf();if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['all']))customerQuery('UPDATE notifications SET is_read=1 WHERE user_id=?',[$customerId]);else customerQuery('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?',[(int)$_POST['id'],$customerId]);}$notes=customerRows('SELECT id,title,message,type,is_read,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100',[$customerId]);customerPageStart('Notifications','');?><div class="cw-title"><div><h1>Notifications</h1><p>Stay up to date with orders, payments and promotions.</p></div><form method="post"><?=csrfField()?><input type="hidden" name="all" value="1"><button class="cw-btn alt">Mark all as read</button></form></div><section class="cw-card"><?php if(!$notes):?><div class="cw-empty">You're all caught up. No notifications yet.</div><?php else:foreach($notes as $n):?><article style="display:flex;gap:14px;padding:16px 0;border-bottom:1px solid #e7edf5;<?=!$n['is_read']?'background:#f5f8fc':''?>"><span style="font-size:22px"><?=str_contains(strtolower((string)$n['type']),'order')?'📦':'●'?></span><div style="flex:1"><strong><?=e($n['title'])?></strong><p class="muted"><?=e($n['message'])?></p><small class="muted"><?=e($n['created_at'])?></small></div><?php if(!$n['is_read']):?><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=(int)$n['id']?>"><button class="cw-btn alt">Read</button></form><?php endif;?></article><?php endforeach;endif;?></section><?php customerPageEnd();?>